Play a line on the board, or pick one of the 3,810 named openings below it. True reach is the share of games that reach the position by any move order. Because moves alternate, the share along your move order factorises exactly into W, the product of White’s choices, times B, the product of Black’s. The same factors answer a second question: if you always play the line, you get it whenever your opponent cooperates.
VERSION = "0507bdfbc43a"
asset = (path) =&gt; new URL(`${path}?v=${VERSION}`, document.baseURI).href
dashMod = import(asset("dash.js"))
boardMod = import(asset("board.js"))
controlsMod = import(asset("controls.js"))
exportMod = import(asset("export.js"))
makeStore = dashMod.makeStore
toPlain = dashMod.toPlain
monthDate = dashMod.monthDate
monthLabel = dashMod.monthLabel
createBoard = boardMod.createBoard
multiSelect = controlsMod.multiSelect
bandSummary = controlsMod.bandSummary
chartWithDownload = exportMod.chartWithDownload
exportChart = exportMod.exportChart
EXPORT_FONT = exportMod.EXPORT_FONT
slugify = exportMod.slug
Plot = import("https://cdn.jsdelivr.net/npm/@observablehq/plot@0.6.16/+esm")
ChessLib = import("https://cdn.jsdelivr.net/npm/chess.js@1.4.0/dist/esm/chess.js")
store = makeStore("data", VERSION)
ix = store.loadIndex()
COL = ({ white: "#2a78d6", black: "#eb6834", draw: "#b9b8b0", reach: "#1baf7a", prod: "#52514e", ink: "#0b0b0b", muted: "#898781", grid: "#e1e0d9" })
M = ix.n_months
openingRows = ix.openings.map((o) =&gt; ({ id: o.id, eco: o.eco, name: o.name, moves: ix.pgn(o.moves), line: o.moves, plies: o.moves.length, rank: o.rank }))
ITALIAN = ["e4", "e5", "Nf3", "Nc6", "Bc4"]
// Shareable state in the URL hash:
//   #moves=e4,e5,Nf3&speeds=Blitz,Rapid&bands=1600,1800&from=2019-01&to=2021-12&smooth=3&view=levels
//   (from= defaults to 2017-01 and to= to the latest month; both are written only when they differ)
// (#opening=&lt;id&gt; from v1 links still works: it sets the board to that line)
hashParams = new URLSearchParams(location.hash.slice(1))
hashList = (k) =&gt; hashParams.has(k) ? hashParams.get(k).split(",").filter(Boolean) : null
monthIndex = (s) =&gt; {
  const m = /^(\d{4})-(\d{2})$/.exec(s ?? "");
  const [y0, mm0] = ix.first_month.split("-").map(Number);
  return m ? Math.max(0, Math.min(M - 1, (+m[1] - y0) * 12 + (+m[2] - mm0))) : null;
}
// The window opens on 2017-01 .. latest month by default (2013-2016 is the early,
// thin Lichess era); #from= / #to= override it. A link that gives only an early
// #to= (v1.4 omitted from= when it was the first month) keeps meaning "from the start".
DEFAULT_FROM = monthIndex("2017-01") ?? 0
hashMonth = (k, dflt) =&gt; monthIndex(hashParams.get(k)) ?? dflt
fromDefault = (hashMonth("to", M - 1) &lt; DEFAULT_FROM) ? 0 : DEFAULT_FROM
initialMoves = hashList("moves") ?? (hashParams.has("opening") ? ix.byId.get(+hashParams.get("opening"))?.moves : null) ?? ITALIAN
// picking a named opening sets the board to its line
{ if (pick) viewof line.setLine(pick.line); }
m0 = Math.min(period.from, period.to)
m1 = Math.max(period.from, period.to)
smooth = pooled ? 3 : 1
res = store.compute(line, speeds, bands, m0, m1, smooth)
inTree = res.line.inTree
treeLine = line.slice(0, inTree)
offTree = inTree &lt; line.length
// the named opening at a node: prefer the one whose moves are exactly this
// line; else the shortest named line ending there (all share the position)
nameAt = (node, moves) =&gt; {
  const c = ix.namesAt.get(node);
  if (!c) return null;
  const key = moves.join(" ");
  return c.find((o) =&gt; o.moves.join(" ") === key) ?? [...c].sort((a, b) =&gt; a.moves.length - b.moves.length || a.rank - b.rank)[0];
}
// deepest named position along the in-tree part of the line
namedAlong = {
  let v = ix.root, best = null;
  const nodes = [ix.root, ...res.line.edges.map((e) =&gt; e.child)];
  for (let i = nodes.length - 1; i &gt;= 0 && !best; i--) {
    const o = nameAt(nodes[i], treeLine.slice(0, i));
    if (o) best = { o, at: i };
  }
  return best;
}
// a line that left the tree may have come back into it (a transposition
// through positions outside S): recognise the position by its FEN
reentry = offTree ? store.nodeOfFen(viewof line.fen()).then((v) =&gt; (v === null ? null : { node: v, o: nameAt(v, []) })) : null
rows = res.cnt ? d3.range(m0, m1 + 1).map((m, j) =&gt; {
  const s = res.ser, a = res.att;
  const r = { m, date: monthDate(ix, m), label: monthLabel(ix, m) };
  for (const k of ["W", "B", "WxB", "reach", "gap", "E_white", "E_black", "edge_white", "edge_black",
                   "edge_white_reach", "edge_black_reach", "W_lo", "W_hi", "B_lo", "B_hi", "reach_lo", "reach_hi"])
    r[k] = Number.isFinite(s[k][m]) ? s[k][m] : NaN;
  r.c_W = a.c_W[j]; r.c_B = a.c_B[j]; r.c_total = a.c_total[j];
  return r;
}) : []
win = res.cnt ? res.win : ({ c: [], T: [], n: [] })
popNote = {
  const sp = speeds.length === ix.speeds.length ? "all speeds" : (speeds.join(" + ") || "no speeds");
  const bl = bands.length === ix.bands.length ? "all ratings" : (bands.map((b) =&gt; ix.band_labels[ix.bands.indexOf(b)]).join(", ") || "no ratings");
  return `Lichess rated standard games (no arena/swiss, no bots), ${monthLabel(ix, m0)}–${monthLabel(ix, m1)}, ${sp}, ${bl}. `
    + (smooth === 3 ? "Monthly, counts pooled over 3 months." : "Monthly.");
}
pct = (x, d = 1) =&gt; !Number.isFinite(x) ? "—" : x &gt;= 0.1 ? `${(100 * x).toFixed(d)}%` : x &gt;= 0.001 ? `${(100 * x).toFixed(d + 1)}%` : `${(100 * x).toPrecision(2)}%`
tickPct = (d) =&gt; d3.format("~%")(+d.toPrecision(6))
// Log-axis ticks at 1/2/3/5, 1/3 or 1 x 10^k depending on the span, so a wide
// range never draws a thicket of unlabeled minor ticks.
logTicks = (vals) =&gt; {
  const v = vals.filter((x) =&gt; Number.isFinite(x) && x &gt; 0);
  if (!v.length) return undefined;
  const lo = d3.min(v), hi = d3.max(v), span = Math.log10(hi / lo);
  if (span &lt; 0.6) return d3.ticks(lo, hi, 5).filter((t) =&gt; t &gt; 0);   // narrow range: plain nice ticks
  const mult = span &gt; 2.5 ? [1] : span &gt; 1.2 ? [1, 3] : [1, 2, 3, 5];
  const out = [];
  for (let e = Math.floor(Math.log10(lo)) - 1; e &lt;= Math.ceil(Math.log10(hi)); e++)
    for (const mlt of mult) { const t = +(mlt * 10 ** e).toPrecision(6); if (t &gt;= lo / 1.15 && t &lt;= hi * 1.15) out.push(t); }
  return out.length &gt;= 2 ? out : undefined;
}
oneIn = (p) =&gt; !Number.isFinite(p) || p &lt;= 0 ? "—" : p &gt;= 0.5 ? `1 in ${(1 / p).toFixed(1)}` : `1 in ${d3.format(",")(Math.round(1 / p))}`
times = (x) =&gt; !Number.isFinite(x) ? "—" : x &gt;= 10 ? `${d3.format(",")(Math.round(x))}×` : `${x.toFixed(1)}×`
key = (color, kind = "solid") =&gt; `&lt;span class="dash-key ${kind}" style="border-color:${color};${kind === "box" ? `background:${color}` : ""}"&gt;&lt;/span&gt;`
esc = (s) =&gt; String(s).replace(/[&&lt;&gt;"']/g, (c) =&gt; ({ "&": "&amp;", "&lt;": "&lt;", "&gt;": "&gt;", '"': "&quot;", "'": "&#39;" })[c])
D = (s) =&gt; { const d = document.createElement("div"); d.innerHTML = s; return d; }
font = ({ fontFamily: "'Atkinson Hyperlegible', sans-serif", fontSize: "12px", background: "transparent", overflow: "visible" })
lineText = (moves) =&gt; moves.length ? ix.pgn(moves) : "the start position"
// keep the URL in step with the state, so any view can be shared
{
  const p = new URLSearchParams();
  p.set("moves", line.join(","));
  if (speeds.length !== ix.speeds.length) p.set("speeds", speeds.join(","));
  if (bands.length !== ix.bands.length) p.set("bands", bands.join(","));
  if (m0 !== DEFAULT_FROM) p.set("from", monthLabel(ix, m0));
  if (m1 !== M - 1) p.set("to", monthLabel(ix, m1));
  if (smooth === 3) p.set("smooth", "3");
  if (view2 === "Levels") p.set("view", "levels");
  history.replaceState(null, "", "#" + p.toString().replace(/%2C/g, ","));
}








































































































































































chartName = {
  if (!treeLine.length) return { title: "Start position", subtitle: "Move order: none (the start position)", slug: "start-position" };
  const nm = namedAlong;
  const exact = nm && nm.at === treeLine.length && nm.o.moves.join(" ") === treeLine.join(" ");
  const base = nm ? `${nm.o.eco} ${nm.o.name}` : "Unnamed line";
  let subtitle = `Move order: ${ix.pgn(treeLine)}`;
  if (offTree) subtitle += `. The entered line, ${ix.pgn(line)}, leaves the named-opening tree after this; the chart follows it up to here.`;
  return {
    title: exact ? base : `${base} (via ${ix.pgn(treeLine)})`,
    subtitle,
    slug: nm ? `${nm.o.eco}_${slugify(nm.o.name)}` : "line",
  };
}
exportSpec = (panel, panelSlug, build, legend) =&gt; ({
  build, legend,
  title: `${chartName.title} — ${panel}`,
  subtitle: chartName.subtitle,
  footer: popNote,
  source: "Source: dnield.com/openings · Lichess open database",
  filename: `opening_${chartName.slug}_${panelSlug}_${monthLabel(ix, m0)}_${monthLabel(ix, m1)}.png`,
})
exportFontStyle = (fontFamily) =&gt; fontFamily ? { ...font, fontFamily, fontSize: "13px" } : font
// gate-4 hook: the page's own numbers for any line, read back through the browser pane
{
  window.dashCompute = async (moves, sp, bd, a, b, sm) =&gt; {
    const r = await store.compute(moves, sp, bd, a, b, sm);
    const out = toPlain(r, a, b);
    out.explorer = await store.explorer(r.line.node, sp, bd, a, b);
    return out;
  };
  window.dashIndex = ix;
  return true;
}
res.cnt ? html`` : D(`&lt;p class="dash-callout"&gt;Make a move on the board (or pick a named opening) to see its popularity, who drives it, and how often each side meets it.&lt;/p&gt;`)

2 · Who moved it, White or Black?

viewof view2 = Inputs.radio(["Attribution", "Levels"], { label: "View", value: hashParams.get("view") === "levels" ? "Levels" : "Attribution" })







view2 === "Levels" ? D(`&lt;p class="dash-sub"&gt;&lt;b&gt;W&lt;/b&gt; = how often White makes White's moves on the line when offered the
chance (1st move included); &lt;b&gt;B&lt;/b&gt; = the same for Black. W × B is the dashed line in panel 1.&lt;/p&gt;
&lt;div class="dash-legend"&gt;&lt;span&gt;${key(COL.white)} W: White steers here&lt;/span&gt;&lt;span&gt;${key(COL.black)} B: Black allows it&lt;/span&gt;
&lt;span&gt;shaded: 95% interval&lt;/span&gt;&lt;/div&gt;`)
: D(`&lt;p class="dash-sub"&gt;Change since the start of the window (first 12 months, geometric mean). On a log scale the two
contributions add up exactly to the net change, with no interaction left over.&lt;/p&gt;
&lt;div class="dash-legend"&gt;&lt;span&gt;${key(COL.white, "box")} White's contribution&lt;/span&gt;&lt;span&gt;${key(COL.black, "box")} Black's contribution&lt;/span&gt;
&lt;span&gt;${key(COL.ink)} Net change in W×B&lt;/span&gt;&lt;/div&gt;`)







chart2 = (w, fontFamily) =&gt; {
  if (view2 === "Levels") {
    return Plot.plot({
      width: w, height: 300, marginLeft: 68, marginTop: 30, style: exportFontStyle(fontFamily),
      x: { type: "utc", label: null, domain: [monthDate(ix, m0), monthDate(ix, m1)] },
      y: { type: scale1, label: "probability", tickFormat: tickPct, grid: true, ...(scale1 === "log" ? { ticks: logTicks(rows.flatMap((d) =&gt; [d.W_lo, d.W_hi, d.B_lo, d.B_hi])) } : { nice: true }) },
      marks: [
        Plot.areaY(rows, { x: "date", y1: "W_lo", y2: "W_hi", fill: COL.white, fillOpacity: 0.15, curve: "monotone-x" }),
        Plot.areaY(rows, { x: "date", y1: "B_lo", y2: "B_hi", fill: COL.black, fillOpacity: 0.15, curve: "monotone-x" }),
        Plot.lineY(rows, { x: "date", y: "W", stroke: COL.white, strokeWidth: 2, curve: "monotone-x" }),
        Plot.lineY(rows, { x: "date", y: "B", stroke: COL.black, strokeWidth: 2, curve: "monotone-x" }),
        Plot.ruleX(rows, Plot.pointerX({ x: "date", stroke: COL.muted, strokeWidth: 1 })),
        Plot.tip(rows, Plot.pointerX({ x: "date", y: "W",
          title: (d) =&gt; `${d.label}\nW (White)  ${pct(d.W)}  (${pct(d.W_lo)}–${pct(d.W_hi)})\nB (Black)  ${pct(d.B)}  (${pct(d.B_lo)}–${pct(d.B_hi)})` })),
      ],
    });
  }
  const long = rows.flatMap((d) =&gt; [
    { date: d.date, side: "W", v: d.c_W, label: d.label },   // not "White"/"Black": Plot would
    { date: d.date, side: "B", v: d.c_B, label: d.label },   // read those as CSS colours
  ]).filter((d) =&gt; Number.isFinite(d.v));
  const ext = d3.extent([...long.map((d) =&gt; d.v), ...rows.map((d) =&gt; d.c_total).filter(Number.isFinite),
    ...rows.map((d) =&gt; Math.max(0, d.c_W) + Math.max(0, d.c_B)).filter(Number.isFinite),
    ...rows.map((d) =&gt; Math.min(0, d.c_W) + Math.min(0, d.c_B)).filter(Number.isFinite), 0]);
  const cands = [-0.9, -0.75, -0.5, -0.33, -0.2, -0.1, 0, 0.1, 0.25, 0.5, 0.75, 1, 2, 4, 9];
  const ticks = cands.map((p) =&gt; Math.log(1 + p)).filter((t) =&gt; t &gt;= ext[0] - 0.05 && t &lt;= ext[1] + 0.05);
  const fmt = (t) =&gt; { const p = Math.exp(t) - 1; return Math.abs(p) &lt; 1e-9 ? "0%" : `${p &gt; 0 ? "+" : ""}${Math.round(100 * p)}%`; };
  return Plot.plot({
    width: w, height: 300, marginLeft: 68, marginTop: 30, style: exportFontStyle(fontFamily),
    x: { type: "utc", label: null, domain: [monthDate(ix, m0), d3.utcMonth.offset(monthDate(ix, m1), 1)] },
    y: { label: "change vs window start (log scale)", ticks, tickFormat: fmt, grid: true },
    color: { domain: ["W", "B"], range: [COL.white, COL.black] },
    marks: [
      Plot.rectY(long, { x: "date", interval: "month", y: "v", fill: "side", order: ["W", "B"], insetLeft: 0.5, insetRight: 0.5, fillOpacity: 0.9 }),
      Plot.ruleY([0], { stroke: COL.ink, strokeOpacity: 0.4 }),
      Plot.lineY(rows, { x: (d) =&gt; d3.utcDay.offset(d.date, 14), y: "c_total", stroke: COL.ink, strokeWidth: 1.5 }),
      Plot.ruleX(rows, Plot.pointerX({ x: (d) =&gt; d3.utcDay.offset(d.date, 14), stroke: COL.muted, strokeWidth: 1 })),
      Plot.tip(rows, Plot.pointerX({ x: (d) =&gt; d3.utcDay.offset(d.date, 14), y: "c_total",
        title: (d) =&gt; `${d.label}\nNet    ${fmt(d.c_total)}\nWhite  ${fmt(d.c_W)}\nBlack  ${fmt(d.c_B)}\n(log contributions add: ${d.c_W?.toFixed(3)} + ${d.c_B?.toFixed(3)} = ${d.c_total?.toFixed(3)})` })),
    ],
  });
}







chartWithDownload(chart2(Math.max(240, Math.min(width, 1100))), () =&gt; view2 === "Levels"
  ? exportSpec("Who moved it: W and B", "who-moved-it-levels", (w) =&gt; chart2(w, EXPORT_FONT), [
      { label: "W: White steers here", color: COL.white, kind: "line" },
      { label: "B: Black allows it", color: COL.black, kind: "line" },
      { label: "shaded: 95% interval", color: COL.muted, kind: "area" }])
  : exportSpec("Who moved it: change since the window start", "who-moved-it-attribution", (w) =&gt; chart2(w, EXPORT_FONT), [
      { label: "White's contribution", color: COL.white, kind: "box" },
      { label: "Black's contribution", color: COL.black, kind: "box" },
      { label: "Net change in W×B (log scale; the parts add exactly)", color: COL.ink, kind: "line" }]))







{
  const fmt = (t) =&gt; !Number.isFinite(t) ? "—" : `${t &gt;= 0 ? "+" : ""}${Math.round(100 * (Math.exp(t) - 1))}%`;
  const last = rows.filter((d) =&gt; Number.isFinite(d.c_total)).slice(-12);
  const g = (k) =&gt; last.length ? d3.mean(last, (d) =&gt; d[k]) : NaN;
  return html`&lt;div class="dash-note"&gt;${popNote}&lt;/div&gt;
  ${view2 === "Attribution" ? html`&lt;p class="dash-copy"&gt;Last 12 months vs the first 12 of the window: net &lt;b&gt;${fmt(g("c_total"))}&lt;/b&gt;
  = White &lt;b&gt;${fmt(g("c_W"))}&lt;/b&gt; and Black &lt;b&gt;${fmt(g("c_B"))}&lt;/b&gt; (log contributions, so they add exactly).&lt;/p&gt;` : ""}`;
}

3 · How often would you see it, and how often would your opponent?

// Local to this panel. Default: the side that plays the line's last move,
// i.e. the side "choosing" the opening.
viewof persp = Inputs.select(["White", "Black", "Both sides"], { label: "Perspective",
  value: inTree === 0 ? "Both sides" : inTree % 2 ? "White" : "Black" })







{
  const P = persp;
  const tile = (k, v, s, color) =&gt; `&lt;div class="dash-tile"&gt;&lt;div class="k"&gt;${color ? key(color) : ""}${k}&lt;/div&gt;&lt;div class="v"&gt;${v}&lt;/div&gt;&lt;div class="s"&gt;${s}&lt;/div&gt;&lt;/div&gt;`;
  const typical = tile("Typical opponent meets it", oneIn(win.WxB), `along this move order; ${oneIn(win.reach)} by any order`, COL.prod);
  let tiles;
  if (P === "Both sides") {
    tiles = [
      tile("A White specialist gets it", oneIn(win.E_white), `E&lt;sub&gt;White&lt;/sub&gt; = B: Black's moves decide · edge ${times(win.edge_white)}`, COL.white),
      tile("A Black specialist gets it", oneIn(win.E_black), `E&lt;sub&gt;Black&lt;/sub&gt; = W: White's moves decide · edge ${times(win.edge_black)}`, COL.black),
      typical,
    ];
  } else {
    const w = P === "White";
    const Eyou = w ? win.E_white : win.E_black, edge = w ? win.edge_white : win.edge_black, edgeR = w ? win.edge_white_reach : win.edge_black_reach;
    tiles = [
      tile(`You (always play ${P}'s moves)`, oneIn(Eyou), `E&lt;sub&gt;${P}&lt;/sub&gt; = ${w ? "B" : "W"}: your opponent's moves decide`, w ? COL.white : COL.black),
      typical,
      tile("Your familiarity edge", times(edge), `E&lt;sub&gt;you&lt;/sub&gt; ÷ (W×B) = 1 ÷ ${w ? "W" : "B"} · vs true reach ${times(edgeR)}`),
    ];
  }
  return D(`&lt;div class="dash-tiles"&gt;${tiles.join("")}&lt;/div&gt;`);
}







series3 = persp === "Both sides"
  ? [{ k: "E_white", name: "White specialist", color: COL.white }, { k: "E_black", name: "Black specialist", color: COL.black }]
  : [{ k: persp === "White" ? "E_white" : "E_black", name: `You (${persp})`, color: persp === "White" ? COL.white : COL.black }]







chart3 = (w, fontFamily) =&gt; {
  const inv = (x) =&gt; Number.isFinite(x) && x &gt; 0 ? 1 / x : NaN;
  return Plot.plot({
    width: w, height: 280, marginLeft: 76, marginTop: 30, style: exportFontStyle(fontFamily),
    x: { type: "utc", label: null, domain: [monthDate(ix, m0), monthDate(ix, m1)] },
    y: { type: "log", label: "once every … games", grid: true, tickFormat: (d) =&gt; `1 in ${d3.format("~s")(d)}`,
         ticks: logTicks(rows.flatMap((d) =&gt; [...series3.map((s) =&gt; inv(d[s.k])), inv(d.WxB), inv(d.reach)])) },
    marks: [
      ...series3.map((s) =&gt; Plot.lineY(rows, { x: "date", y: (d) =&gt; inv(d[s.k]), stroke: s.color, strokeWidth: 2, curve: "monotone-x" })),
      Plot.lineY(rows, { x: "date", y: (d) =&gt; inv(d.WxB), stroke: COL.prod, strokeWidth: 2, strokeDasharray: "5,4", curve: "monotone-x" }),
      Plot.lineY(rows, { x: "date", y: (d) =&gt; inv(d.reach), stroke: COL.reach, strokeWidth: 1.5, curve: "monotone-x" }),
      Plot.ruleX(rows, Plot.pointerX({ x: "date", stroke: COL.muted, strokeWidth: 1 })),
      Plot.tip(rows, Plot.pointerX({ x: "date", y: (d) =&gt; inv(d.WxB),
        title: (d) =&gt; [d.label, ...series3.map((s) =&gt; `${s.name}  ${oneIn(d[s.k])}`), `Typical (W×B)  ${oneIn(d.WxB)}`, `Typical (reach)  ${oneIn(d.reach)}`].join("\n") })),
    ],
  });
}







{
  const legend3 = [...series3.map((s) =&gt; ({ label: s.name, color: s.color, kind: "line" })),
    { label: "Typical opponent (W×B)", color: COL.prod, kind: "dashed" },
    { label: "Typical, any move order (reach)", color: COL.reach, kind: "line" }];
  const legend = legend3.map((l) =&gt; `&lt;span&gt;${key(l.color, l.kind === "dashed" ? "dashed" : "solid")} ${l.name ?? l.label}&lt;/span&gt;`).join("");
  const panel = persp === "Both sides" ? "White and Black specialists vs a typical opponent" : `You (${persp}) vs your opponent`;
  const box = chartWithDownload(chart3(Math.max(240, Math.min(width, 1100))), () =&gt; exportSpec(panel, "you-vs-opponent", (w) =&gt; chart3(w, EXPORT_FONT), legend3));
  return html`${D(`&lt;div class="dash-legend"&gt;${legend}&lt;/div&gt;`)}${box}&lt;div class="dash-note"&gt;${popNote}&lt;/div&gt;`;
}

4 · The move path

{
  if (!res.cnt) return D(`&lt;p class="dash-note"&gt;No moves yet.&lt;/p&gt;`);
  const c = win.c, T = win.T, n = win.n;
  const fin = c.filter(Number.isFinite);
  const minC = fin.length ? Math.min(...fin) : NaN;
  const body = res.cnt.edges.map((e, i) =&gt; {
    const side = i % 2 === 0 ? "White" : "Black";
    const col = i % 2 === 0 ? COL.white : COL.black;
    const thin = T[i] &lt; 30 || n[i] &lt; 1;
    const label = `${Math.floor(i / 2) + 1}.${i % 2 === 0 ? "" : ".."} ${esc(e.san)}`;
    const bar = Number.isFinite(c[i]) ? `&lt;span class="dash-bar" style="width:${Math.max(1, 160 * c[i])}px;background:${col}"&gt;&lt;/span&gt;` : "";
    return `&lt;tr class="${c[i] === minC ? "rare" : ""}"&gt;&lt;td&gt;${i + 1}&lt;/td&gt;&lt;td&gt;${key(col)} ${side}&lt;/td&gt;&lt;td class="dash-moves"&gt;${label}&lt;/td&gt;
      &lt;td class="num"&gt;${thin ? `&lt;span class="dash-gap"&gt;${pct(c[i])}&lt;/span&gt;` : pct(c[i])}&lt;/td&gt;&lt;td&gt;${bar}&lt;/td&gt;
      &lt;td class="num"&gt;${d3.format(",")(n[i])}&lt;/td&gt;&lt;td class="num"&gt;${d3.format(",")(T[i])}&lt;/td&gt;&lt;/tr&gt;`;
  }).join("");
  return D(`&lt;p class="dash-sub"&gt;Each move's share among the games that reached the position before it, pooled over the window.
  W multiplies the blue rows and B the orange ones. The rarest move is highlighted.&lt;/p&gt;
  &lt;table class="dash-path"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;Ply&lt;/th&gt;&lt;th&gt;Side&lt;/th&gt;&lt;th&gt;Move&lt;/th&gt;&lt;th class="num"&gt;c&lt;sub&gt;i&lt;/sub&gt;&lt;/th&gt;&lt;th&gt;&lt;/th&gt;
  &lt;th class="num"&gt;Played&lt;/th&gt;&lt;th class="num"&gt;Reached&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;${body}&lt;/tbody&gt;&lt;/table&gt;
  &lt;p class="dash-copy"&gt;Window: W = &lt;b&gt;${pct(win.W)}&lt;/b&gt;, B = &lt;b&gt;${pct(win.B)}&lt;/b&gt;, W×B = &lt;b&gt;${pct(win.WxB)}&lt;/b&gt;,
  true reach = &lt;b&gt;${pct(win.reach)}&lt;/b&gt; of ${d3.format(",")(win.N)} games.&lt;/p&gt;
  &lt;div class="dash-note"&gt;${popNote}&lt;/div&gt;`);
}
